SELECT  FROM moderation_terms

ORDER BY is_exemption, category, normalized_term
LIMIT #{limit} OFFSET #{offset}

SELECT id, term_id, action, before_value::text AS before_value,
       after_value::text AS after_value, changed_by, changed_at
FROM moderation_term_audit
WHERE term_id = #{termId}
ORDER BY changed_at DESC
LIMIT #{limit}
